import ast
import os
import pathlib
import subprocess
import sys
import sysconfig


def diagnose_import(name, directory):
    root = pathlib.Path(directory).resolve()
    if not isinstance(name, str) or not name.isidentifier() or name not in sys.stdlib_module_names:
        raise ValueError('expected a standard-library module name')
    if not root.is_dir():
        raise ValueError('directory must exist')
    probe = "import importlib,sys; sys.dont_write_bytecode=True; m=importlib.import_module(sys.argv[1]); print('\\nOPSFORGE_ORIGIN:'+ascii(getattr(m,'__file__',None) or m.__spec__.origin or ''))"
    env = {key: value for key, value in os.environ.items() if key not in ('PYTHONPATH', 'PYTHONHOME')}
    proc = subprocess.run([sys.executable, '-E', '-c', probe, name], cwd=root,
                          env=env, capture_output=True, text=True, timeout=5, check=False)
    if proc.returncode:
        return {'ok': False, 'shadowed': False, 'origin': None, 'error': proc.stderr[-500:],
                'remediation': 'inspect import traceback and sys.path'}
    lines = [line[len('OPSFORGE_ORIGIN:'):] for line in proc.stdout.splitlines()
             if line.startswith('OPSFORGE_ORIGIN:')]
    origin_value = ast.literal_eval(lines[-1])
    special = origin_value in ('built-in', 'frozen')
    origin = origin_value if special else pathlib.Path(origin_value).resolve()
    stdlib = pathlib.Path(sysconfig.get_path('stdlib')).resolve()
    def beneath(path, parent):
        try:
            path.relative_to(parent)
            return True
        except ValueError:
            return False
    shadowed = False if special else beneath(origin, root) or not beneath(origin, stdlib)
    local_files = [str(path) for path in (root / (name + '.py'), root / name / '__init__.py') if path.is_file()]
    return {'ok': True, 'shadowed': shadowed, 'origin': str(origin), 'local_candidates': local_files,
            'remediation': ('rename conflicting local module/package, remove its matching stale __pycache__ entry, then verify in a fresh process'
                            if shadowed else 'standard-library origin verified')}
